`default_nettype none

// DDR3 controller + llm_core (UART commands, matmul engine, microSD). See
// llm_core.sv for the command set.
//
// The DDR controller (mig_ddr3, generated by scripts/gen_ip.tcl from
// Digilent's preset) takes the 200 MHz board clock and runs the DDR3 at
// 1800 MT/s; everything else runs on its 225 MHz user clock. CPU RESET resets
// the controller too, which recalibrates.
module top_llm #(
    parameter int Baud = 3_000_000
) (
    input wire logic sysclk_p,
    input wire logic sysclk_n,
    input wire logic cpu_resetn,
    input wire logic uart_rx_i,
    output logic uart_tx_o,
    output logic [7:0] led_o,

    inout wire [31:0] ddr3_dq,
    inout wire [3:0] ddr3_dqs_n,
    inout wire [3:0] ddr3_dqs_p,
    output logic [14:0] ddr3_addr,
    output logic [2:0] ddr3_ba,
    output logic ddr3_ras_n,
    output logic ddr3_cas_n,
    output logic ddr3_we_n,
    output logic ddr3_reset_n,
    output logic [0:0] ddr3_ck_p,
    output logic [0:0] ddr3_ck_n,
    output logic [0:0] ddr3_cke,
    output logic [0:0] ddr3_cs_n,
    output logic [3:0] ddr3_dm,
    output logic [0:0] ddr3_odt,

    // microSD slot, used in SPI mode (DAT1 / DAT2 unused)
    output logic sd_reset,  // power switch: low = card powered
    output logic sd_sclk,
    output logic sd_cmd,  // MOSI
    output logic sd_dat3,  // chip select
    input wire logic sd_dat0,  // MISO
    input wire logic sd_cd  // card detect
);

  localparam int AddrW = 30;

  logic ui_clk, ui_rst, calib_done, mmcm_locked;
  logic aresetn_q, rst_n_q;

  logic [AddrW-1:0] awaddr, araddr;
  logic [7:0] awlen, arlen;
  logic awvalid, awready, wlast, wvalid, wready, bvalid, bready;
  logic arvalid, arready, rvalid, rready, rlast;
  logic [255:0] wdata, rdata;
  logic [31:0] wstrb;
  logic [2:0] bid, rid;
  logic [1:0] bresp, rresp;

  mig_ddr3 u_mig (
      .ddr3_dq(ddr3_dq),
      .ddr3_dqs_n(ddr3_dqs_n),
      .ddr3_dqs_p(ddr3_dqs_p),
      .ddr3_addr(ddr3_addr),
      .ddr3_ba(ddr3_ba),
      .ddr3_ras_n(ddr3_ras_n),
      .ddr3_cas_n(ddr3_cas_n),
      .ddr3_we_n(ddr3_we_n),
      .ddr3_reset_n(ddr3_reset_n),
      .ddr3_ck_p(ddr3_ck_p),
      .ddr3_ck_n(ddr3_ck_n),
      .ddr3_cke(ddr3_cke),
      .ddr3_cs_n(ddr3_cs_n),
      .ddr3_dm(ddr3_dm),
      .ddr3_odt(ddr3_odt),
      .sys_clk_p(sysclk_p),
      .sys_clk_n(sysclk_n),
      .ui_clk(ui_clk),
      .ui_clk_sync_rst(ui_rst),
      .mmcm_locked(mmcm_locked),
      .aresetn(aresetn_q),
      .app_sr_req(1'b0),
      .app_ref_req(1'b0),
      .app_zq_req(1'b0),
      .app_sr_active(),
      .app_ref_ack(),
      .app_zq_ack(),
      .s_axi_awid(3'd0),
      .s_axi_awaddr(awaddr),
      .s_axi_awlen(awlen),
      .s_axi_awsize(3'd5),  // 32 bytes per beat
      .s_axi_awburst(2'b01),  // INCR
      .s_axi_awlock(1'b0),
      .s_axi_awcache(4'b0011),
      .s_axi_awprot(3'b000),
      .s_axi_awqos(4'd0),
      .s_axi_awvalid(awvalid),
      .s_axi_awready(awready),
      .s_axi_wdata(wdata),
      .s_axi_wstrb(wstrb),
      .s_axi_wlast(wlast),
      .s_axi_wvalid(wvalid),
      .s_axi_wready(wready),
      .s_axi_bready(bready),
      .s_axi_bid(bid),
      .s_axi_bresp(bresp),
      .s_axi_bvalid(bvalid),
      .s_axi_arid(3'd0),
      .s_axi_araddr(araddr),
      .s_axi_arlen(arlen),
      .s_axi_arsize(3'd5),
      .s_axi_arburst(2'b01),
      .s_axi_arlock(1'b0),
      .s_axi_arcache(4'b0011),
      .s_axi_arprot(3'b000),
      .s_axi_arqos(4'd0),
      .s_axi_arvalid(arvalid),
      .s_axi_arready(arready),
      .s_axi_rready(rready),
      .s_axi_rid(rid),
      .s_axi_rdata(rdata),
      .s_axi_rresp(rresp),
      .s_axi_rlast(rlast),
      .s_axi_rvalid(rvalid),
      .init_calib_complete(calib_done),
      .device_temp(),
      .sys_rst(cpu_resetn)
  );

  // AXI reset for the controller's AXI shim, and the core's reset: released
  // once the user clock domain is out of reset
  always_ff @(posedge ui_clk) begin
    aresetn_q <= ~ui_rst;
    rst_n_q   <= ~ui_rst;
  end

  llm_core #(
      .ClkHz(225_000_000),
      .Baud (Baud),
      .AddrW(AddrW)
  ) u_core (
      .clk_i(ui_clk),
      .rst_ni(rst_n_q),
      .calib_done_i(calib_done),
      .uart_rx_i(uart_rx_i),
      .uart_tx_o(uart_tx_o),
      .led_o(led_o),
      .m_awaddr_o(awaddr),
      .m_awlen_o(awlen),
      .m_awvalid_o(awvalid),
      .m_awready_i(awready),
      .m_wdata_o(wdata),
      .m_wstrb_o(wstrb),
      .m_wlast_o(wlast),
      .m_wvalid_o(wvalid),
      .m_wready_i(wready),
      .m_bvalid_i(bvalid),
      .m_bready_o(bready),
      .m_araddr_o(araddr),
      .m_arlen_o(arlen),
      .m_arvalid_o(arvalid),
      .m_arready_i(arready),
      .m_rdata_i(rdata),
      .m_rvalid_i(rvalid),
      .m_rready_o(rready),
      .sd_power_n_o(sd_reset),
      .sd_sclk_o(sd_sclk),
      .sd_cs_o(sd_dat3),
      .sd_mosi_o(sd_cmd),
      .sd_miso_i(sd_dat0),
      .sd_cd_i(sd_cd),
      // no CPU here
      .s_awaddr_i('0),
      .s_awvalid_i(1'b0),
      .s_awready_o(),
      .s_wdata_i('0),
      .s_wvalid_i(1'b0),
      .s_wready_o(),
      .s_bvalid_o(),
      .s_bready_i(1'b1),
      .s_araddr_i('0),
      .s_arvalid_i(1'b0),
      .s_arready_o(),
      .s_rdata_o(),
      .s_rvalid_o(),
      .s_rready_i(1'b1),
      .yb_clk_i(ui_clk),
      .yb_en_i(1'b0),
      .yb_we_i('0),
      .yb_addr_i('0),
      .yb_din_i('0),
      .yb_dout_o()
  );

endmodule

`default_nettype wire
